function renderProducts(){const available=state.products.filter(p=>Number(p.stock_milli)>0);const availableCategories=[...new Set(available.map(p=>p.category).filter(Boolean))];const cats=$('categories');cats.innerHTML=['<button class="category '+(!state.category?'active':'')+'" data-category="">Todos</button>',...availableCategories.map(c=>`<button class="category ${state.category===c?'active':''}" data-category="${esc(c)}">${esc(c)}</button>`)].join('');cats.querySelectorAll('button').forEach(button=>button.onclick=()=>{state.category=button.dataset.category;loadProducts().catch(e=>toast(e.message,true))});const visible=state.category?available.filter(p=>p.category===state.category):available;$('productsGrid').innerHTML=visible.length?visible.map(p=>`<button class="product" data-id="${esc(p.id)}"><img class="product-image" src="${esc(productImageUrl(p))}" alt="" loading="lazy" onerror="this.src='/static/product-images/generic.svg'"><span><span class="name">${esc(p.name)}</span><span class="meta">${esc(productCodeMeta(p))}</span></span><span><span class="price">${money(p.price_cents)}/${esc(p.unit)}</span><span class="stock">${qtyText(p.stock_milli,p.unit)} ${esc(p.unit)} em estoque</span></span></button>`).join(''):'<div class="empty-state" style="min-height:170px;grid-column:1/-1">Nenhum produto com estoque disponível neste terminal. Clique em “Atualizar catálogo” ou registre uma entrada no painel da empresa.</div>';$('productsGrid').querySelectorAll('.product').forEach(b=>b.onclick=()=>addProduct(b.dataset.id).catch(e=>toast(e.message,true)))}
async function addProduct(id,quantityOverride=null){const p=state.products.find(x=>x.id===id);if(!p)return;if(Number(p.stock_milli)<=0){toast('Produto sem estoque disponível neste terminal',true);return}let quantity=quantityOverride;if(p.unit==='KG'&&quantity===null){if(state.scale.port){const existing=state.cart.find(x=>x.id===id);if(existing)existing.quantity_milli=0;else state.cart.push({...p,quantity_milli:0});state.scale.targetId=id;state.saleRequest=null;state.discountApproval=null;renderCart();scaleStatus(`Aguardando peso de ${p.name} · coloque o produto na balança`,'active');toast('Coloque o produto na balança para capturar o peso');return}const raw=await textDialog('Informar peso do produto','Este produto é vendido por quilo. Digite o peso ou conecte uma balança serial.','Ex.: 0,350','text',{eyebrow:'Venda por peso',fieldLabel:'Peso (kg)',acceptLabel:'Adicionar peso',icon:'⚖',validate:async value=>{const parsed=parseQty(value);if(parsed<=0)throw Error('Informe um peso maior que zero');if(parsed>1000000)throw Error('Peso acima do limite permitido')}});if(!raw)return;quantity=parseQty(raw)}if(quantity===null)quantity=1000;if(!Number.isSafeInteger(quantity)||quantity<=0)throw Error('Peso inválido');const existing=state.cart.find(x=>x.id===id);if(existing)existing.quantity_milli+=quantity;else state.cart.push({...p,quantity_milli:quantity});state.scale.targetId=id;state.saleRequest=null;state.discountApproval=null;renderCart();$('productSearch').focus()}
function cartGross(){return state.cart.reduce((sum,p)=>sum+Math.round(p.price_cents*p.quantity_milli/1000),0)}
function requestedDiscount(){try{return parsePercent($('discountInput').value)}catch{return 0}}
function discountAmount(percent){return Math.min(cartGross(),Math.round(cartGross()*percent/100))}
function appliedDiscount(){const requested=requestedDiscount();return state.discountApproval?.percent===requested?state.discountApproval.amountCents:0}
function renderDiscountState(){const requested=requestedDiscount(),approved=appliedDiscount(),approvedPercent=state.discountApproval?.percent||0,status=$('discountStatus'),button=$('applyDiscountBtn');if(!status||!button)return;if(approved){status.textContent=`Desconto de ${approvedPercent.toLocaleString('pt-BR',{maximumFractionDigits:2})}% (${money(approved)}) autorizado pelo gerente.`;status.className='discount-status approved';button.textContent='Alterar desconto'}else if(requested){status.textContent='Clique em “Aplicar desconto” para solicitar a autorização do gerente.';status.className='discount-status pending';button.textContent='Aplicar desconto'}else{status.textContent='Digite o percentual e clique em Aplicar desconto.';status.className='discount-status';button.textContent='Aplicar desconto'}}
async function applyDiscount(){const requested=requestedDiscount(),requestedCents=discountAmount(requested);if(!requested){state.discountApproval={percent:0,amountCents:0,managerPin:''};renderDiscountState();renderCart();toast('Desconto removido');return}if(!state.cart.length)throw Error('Adicione um produto antes de aplicar desconto');if(!requestedCents)throw Error('O percentual informado é menor que o mínimo aplicável nesta venda');if(requestedCents>=cartGross())throw Error('O desconto deve ser menor que o total da venda');const pin=await textDialog('Autorizar desconto','Digite o PIN e confirme. A validação acontece agora, respeitando o limite definido pela administração.','Digite o PIN numérico','password',{eyebrow:'Autorização do gerente',fieldLabel:'PIN do gerente',acceptLabel:'Validar e aplicar',icon:'✓',validate:async value=>{await api('/api/discount/authorize','POST',{pin:value,gross_cents:cartGross(),discount_cents:requestedCents})}});if(!pin)return;state.discountApproval={percent:requested,amountCents:requestedCents,managerPin:pin};renderDiscountState();renderCart();toast('Desconto validado e autorizado para esta venda')}
