function paymentMethodLabel(){if(state.paymentMethod==='cash')return 'Dinheiro';if(state.paymentMethod==='pix')return 'Pix';if(state.paymentMethod==='card_credit')return 'Cartão · Crédito';if(state.paymentMethod==='card_debit')return 'Cartão · Débito';if(state.paymentMethod==='split')return 'Pagamento dividido';return ''}
function renderPaymentUI(){const method=state.paymentMethod;const cardMethod=state.cardMethod;document.querySelectorAll('[data-payment-method]').forEach(button=>button.classList.toggle('selected',button.dataset.paymentMethod===(method==='card_credit'||method==='card_debit'?'card':method)));document.querySelectorAll('[data-card-method]').forEach(button=>button.classList.toggle('selected',button.dataset.cardMethod===cardMethod));$('cashPaymentPanel')?.classList.toggle('hidden',method!=='cash');$('cardPaymentPanel')?.classList.toggle('hidden',method!=='card'&&method!=='card_credit'&&method!=='card_debit');$('advancedPaymentPanel')?.classList.toggle('hidden',method!=='split');const advanced=$('splitPaymentToggle');if(advanced){advanced.classList.toggle('active',method==='split');advanced.setAttribute('aria-expanded',String(method==='split'));advanced.textContent=method==='split'?'Voltar ao pagamento simples':'Dividir pagamento'}const summary=$('paymentSelectionSummary');if(summary){if(method==='cash'){summary.textContent='Dinheiro selecionado · informe o valor recebido para calcular o troco.';summary.className='payment-selection-summary selected'}else if(method==='pix'){summary.textContent=`Pix selecionado · confirmar ${money(cartTotal())} no aplicativo do cliente.`;summary.className='payment-selection-summary selected'}else if(method==='card'){summary.textContent='Escolha Crédito ou Débito para confirmar a venda.';summary.className='payment-selection-summary pending'}else if(method==='card_credit'||method==='card_debit'){summary.textContent=`${paymentMethodLabel()} selecionado · confirmar ${money(cartTotal())} na maquininha.`;summary.className='payment-selection-summary selected'}else if(method==='split'){summary.textContent='Informe os valores combinados. O total precisa fechar a venda.';summary.className='payment-selection-summary pending'}else{summary.textContent='Selecione uma forma de pagamento.';summary.className='payment-selection-summary'}}if(method==='pix')setPaymentValue('payPix',cartTotal());if(method==='card_credit'){setPaymentValue('payCredit',cartTotal());setPaymentValue('payDebit',0)}if(method==='card_debit'){setPaymentValue('payDebit',cartTotal());setPaymentValue('payCredit',0)}if(method!=='cash'&&method!=='split')setPaymentValue('payCash',0);renderChange()}
function selectPaymentMethod(method){clearPaymentValues();state.cardMethod=null;state.paymentMethod=method;if(method==='pix')setPaymentValue('payPix',cartTotal());if(method==='cash'){setPaymentValue('payCash',0);setTimeout(()=>$('payCash')?.focus(),0)}renderPaymentUI()}
